#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-21

# Check the macOS unified log for recent sandbox violations (doctor Check 15b)
#
# macOS keeps a system-wide sandbox violation log: every reporting Seatbelt
# denial lands in the unified log as a kernel message with sender "Sandbox"
# ("Sandbox: <proc>(<pid>) deny(1) <operation> <target>"). Nothing in a CC
# session surfaces those, so a hardening config that quietly breaks tooling
# (or a process probing paths it should not) is invisible. This check runs a
# bounded, read-only query over a recent window and reports what it sees.
#
# FAIL-CLOSED CONTRACT: when the log query itself cannot run (the `log` CLI
# refuses inside a sandbox: "log: Cannot run while sandboxed", observed exit
# 64), this script reports UNOBSERVABLE and exits non-zero. It never converts
# "could not look" into "zero violations".
#
# Usage: ./check-sandbox-violations.sh [--window 15m] [--process REGEX] [--json]
#   --window N[smhd]   how far back to query (default 15m; bounded on purpose)
#   --process REGEX    only count deny lines whose process matches (ERE)
#   --json             machine-readable output
#
# Exit codes:
#   0 = observed, no matching deny events in the window
#   1 = observed, at least one deny event in the window
#   2 = UNOBSERVABLE: the log query was denied or failed (fail closed)
#   3 = skipped: not macOS (the unified log is Darwin-only)
#   4 = usage error

set -euo pipefail

WINDOW="15m"
PROC_RE=""
OUTPUT_FORMAT="table"

while [[ $# -gt 0 ]]; do
    case "$1" in
        --window)
            WINDOW="$2"
            shift 2
            ;;
        --process)
            PROC_RE="$2"
            shift 2
            ;;
        --json)
            OUTPUT_FORMAT="json"
            shift
            ;;
        --help|-h)
            sed -n '5,30p' "$0"
            exit 0
            ;;
        *)
            echo "Error: Unknown option '$1'." >&2
            exit 4
            ;;
    esac
done

# Keep the query bounded: refuse open-ended or malformed windows.
if ! [[ "$WINDOW" =~ ^[0-9]+[smhd]$ ]]; then
    echo "Error: --window must look like 15m / 90s / 2h / 1d (got '$WINDOW')." >&2
    exit 4
fi

json_escape() {
    # minimal escaper for strings we embed in JSON output
    printf '%s' "$1" | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g' | tr -d '\n'
}

# =============================================================================
# Platform gate: explicit skip, never a silent pass
# =============================================================================
if [[ "$(uname -s)" != "Darwin" ]]; then
    if [[ "$OUTPUT_FORMAT" == "json" ]]; then
        printf '{"status":"skipped","reason":"unified log is macOS-only (uname: %s)","window":"%s","count":null}\n' \
            "$(json_escape "$(uname -s)")" "$WINDOW"
    else
        echo "Sandbox violations: SKIP: unified log is macOS-only (uname: $(uname -s))"
        echo "    On Linux, sandbox denials surface via auditd/journald, not this check."
    fi
    exit 3
fi

# =============================================================================
# Bounded, read-only unified-log query
# =============================================================================
# Predicate verified live 2026-08-21 on Darwin 25.5.0: reporting Seatbelt
# denials arrive as kernel messages with sender "Sandbox", e.g.
#   kernel[0:...] (Sandbox) Sandbox: ecosystemd(2048) deny(1) file-read-data /Library/Preferences/com.apple.security.plist
ERR_FILE="$(mktemp "${TMPDIR:-/tmp}/sandbox-viol-err-XXXXXX")"
OUT_FILE="$(mktemp "${TMPDIR:-/tmp}/sandbox-viol-out-XXXXXX")"
trap 'rm -f "$ERR_FILE" "$OUT_FILE"' EXIT

LOG_EXIT=0
/usr/bin/log show --last "$WINDOW" --style compact \
    --predicate 'sender == "Sandbox"' \
    >"$OUT_FILE" 2>"$ERR_FILE" || LOG_EXIT=$?

if [[ $LOG_EXIT -ne 0 ]]; then
    # FAIL CLOSED. A denied instrument is a finding, not a zero.
    REASON="$(head -3 "$ERR_FILE" | tr '\n' ' ')"
    [[ -z "$REASON" ]] && REASON="log show exited $LOG_EXIT with no stderr"
    if [[ "$OUTPUT_FORMAT" == "json" ]]; then
        printf '{"status":"unobservable","reason":"%s","log_exit":%d,"window":"%s","count":null}\n' \
            "$(json_escape "$REASON")" "$LOG_EXIT" "$WINDOW"
    else
        echo "Sandbox violations: UNOBSERVABLE: the log query itself was denied (exit $LOG_EXIT)"
        echo "    stderr: $REASON"
        echo "    This is the expected result when doctor runs inside CC's Bash sandbox:"
        echo "    the log CLI refuses sandboxed callers. Re-run from an unsandboxed shell:"
        echo "    /usr/bin/log show --last $WINDOW --style compact --predicate 'sender == \"Sandbox\"'"
        echo "    Do NOT read this as zero violations."
    fi
    exit 2
fi

# =============================================================================
# Count and summarize deny events
# =============================================================================
# Deny lines look like: ... (Sandbox) Sandbox: <proc>(<pid>) deny(1) <op> <target>
DENY_LINES="$(grep -E 'Sandbox: [^ ]+\([0-9]+\) deny\(' "$OUT_FILE" || true)"
if [[ -n "$PROC_RE" ]]; then
    DENY_LINES="$(printf '%s\n' "$DENY_LINES" | grep -E "Sandbox: [^ ]*(${PROC_RE})[^ ]*\([0-9]+\) deny\(" || true)"
fi

if [[ -z "$DENY_LINES" ]]; then
    COUNT=0
else
    COUNT="$(printf '%s\n' "$DENY_LINES" | grep -c . || true)"
fi

# Top (process, operation) pairs: capped output, never the raw firehose.
TOP=""
if [[ "$COUNT" -gt 0 ]]; then
    TOP="$(printf '%s\n' "$DENY_LINES" \
        | sed -E 's/.*Sandbox: ([^ ]+)\([0-9]+\) deny\(([0-9]+)\) ([^ ]+).*/\1 \3/' \
        | sort | uniq -c | sort -rn | head -5)"
fi

if [[ "$OUTPUT_FORMAT" == "json" ]]; then
    printf '{"status":"%s","window":"%s","count":%d,"process_filter":"%s","top":[' \
        "$(if [[ "$COUNT" -eq 0 ]]; then echo ok; else echo violations; fi)" \
        "$WINDOW" "$COUNT" "$(json_escape "$PROC_RE")"
    if [[ -n "$TOP" ]]; then
        FIRST=1
        while IFS= read -r row; do
            [[ $FIRST -eq 1 ]] || printf ','
            printf '"%s"' "$(json_escape "$(echo "$row" | sed -E 's/^ +//')")"
            FIRST=0
        done <<< "$TOP"
    fi
    printf ']}\n'
else
    if [[ "$COUNT" -eq 0 ]]; then
        echo "Sandbox violations: OK: 0 reported deny events in the last $WINDOW${PROC_RE:+ (process filter: $PROC_RE)}"
        echo "    Caveat: sandbox profiles can deny WITHOUT reporting (measured: a denied"
        echo "    write from inside CC's Bash sandbox left no unified-log row), so zero"
        echo "    reported events is not proof of zero denials."
    else
        echo "Sandbox violations: $COUNT reported deny event(s) in the last $WINDOW${PROC_RE:+ (process filter: $PROC_RE)}"
        echo "    Top (count / process / operation):"
        printf '%s\n' "$TOP" | sed 's/^/      /'
        echo "    -> Inspect: /usr/bin/log show --last $WINDOW --style compact --predicate 'sender == \"Sandbox\"'"
        echo "    -> System daemons (ecosystemd, analyticsd, ...) are normal background noise;"
        echo "       investigate rows naming your session's tools (bash, node, python, git)."
    fi
fi

if [[ "$COUNT" -gt 0 ]]; then
    exit 1
fi
exit 0
